    def __init__(self, archive_path):
        self.archive_path = Path(archive_path)

    def backup_files(self, source_dir, backup_mode='zip'):
        if backup_mode == 'zip':
            with zipfile.ZipFile(self.archive_path, 'w') as zipf:
                for root, dirs, files in os.walk(source_dir):
                    for file in files:
                        file_path = os.path.join(root, file)
                        arcname = os.path.relpath(file_path, start=source_dir)
                        zipf.write(file_path, arcname)

    def restore_files(self, extract_to):
        with zipfile.ZipFile(self.archive_path, 'r') as zipf:
            zipf.extractall(path=extract_to)

