import re
from collections import defaultdict
from whoosh.index import create_in, open_dir
from whoosh.fields import Schema, TEXT, KEYWORD
from whoosh.analysis import StemmingAnalyzer

def build_index(directory_path):
    schema = Schema(id=KEYWORD(stored=True), content=TEXT(analyzer=StemmingAnalyzer()))
    ix = create_in(directory_path, schema)

    writer = ix.writer()
    stemmed_words = {}
    doc_id_counter = 0

    for root, dirs, files in os.walk(directory_path):
        for file in files:
            if file.endswith(".txt"):
                with open(os.path.join(root, file)) as f:
                    url = f.readline().strip()
                    content = " ".join(f.readlines())
                    parsed_text = re.sub(r'\W+', ' ', content).lower()

                    words = set(parsed_text.split())
                    stemmed_words[file] = [(word, doc_id_counter) for word in words]

                    writer.add_document(id=file, content=parsed_text)
                    doc_id_counter += 1

    writer.commit()

    inverted_index = defaultdict(list)
    for file, word_list in stemmed_words.items():
        for word, doc_id in word_list:
            inverted_index[word].append(doc_id)

    return inverted_index, stemmed_words, {file: f"{root}/{file}" for root, _, files in os.walk(directory_path) for file in files}

def startIndexer(directory_path):
    global inverted_index, forward_index, id_to_url
    ix = open_dir(directory_path)
    inverted_index = {key: val[:] for key, val in ix.reader().all_terms()}
    forward_index = {entry["id"]: entry["content"] for entry in ix.searcher().search(query.Term("content", "*"))}
    id_to_url = {entry["id"]: entry["url"] for entry in ix.searcher().search(query.Term("content", "*"))}

def finishIndexer():
